redundant_connection_ii.optimal:
find(parent, x): while parent[x] != x: parent[x] = parent[parent[x]], x = parent[x]; return x
parent_of = 0 for every node; cand1 = cand2 = none
for each edge (u, v):
    if parent_of[v] is set: cand1 = [parent_of[v], v], cand2 = [u, v]   (v has two parents)
    else: parent_of[v] = u
parent[x] = x for every node
for each edge (u, v):
    if [u, v] == cand2: continue   (provisionally drop the later of the two parent edges)
    root_u = find(parent, u), root_v = find(parent, v)
    if root_u == root_v:   (a cycle survives even without cand2)
        if cand2 exists: return cand1   (so the earlier parent edge is the culprit)
        return [u, v]   (no double parent: the edge that closes the cycle is it)
    parent[root_v] = root_u
return cand2

number_of_islands_ii.optimal:
find(parent, x): while parent[x] != x: parent[x] = parent[parent[x]], x = parent[x]; return x
parent = empty dict, count = 0, out = []   (union-find keyed by row * n + col, land cells only)
for each (row, col) in positions:
    key = row * n + col
    if key in parent: append count to out; continue   (duplicate add: nothing changes)
    parent[key] = key, count += 1
    for each in-bounds neighbour (nr, nc):
        nb = nr * n + nc
        if nb not in parent: continue   (still water)
        root_new = find(parent, key), root_nb = find(parent, nb)
        if root_new != root_nb:   (a different island; two neighbours may share one root)
            parent[root_nb] = root_new, count -= 1
    append count to out
return out

minimize_malware_spread.brute:
best = -1, best_count = n + 1
for each cand in initial, ascending:   (remove one infected node, simulate the spread)
    infected = every initial node except cand
    stack = list of infected
    while the stack is not empty:
        u = pop the top
        for each v with graph[u][v] == 1 and v not in infected: add v to infected, push v
    if size of infected < best_count: best = cand, best_count = size of infected   (strict: ties keep the earlier)
return best

