largest_component_size_by_common_factor.optimal:
find(parent, x): path-halving root lookup
union(parent, a, b): create a and b on first sight, then parent[find(a)] = find(b)
parent = empty dict   (numbers and prime hubs share one union-find)
for each x in nums:
    rem = x, p = 2
    while p * p <= rem:   (trial division)
        if p divides rem:
            union(parent, x, p)   (number <-> prime hub: two numbers sharing p meet here)
            divide rem by p until it no longer divides
        p += 1
    if rem > 1: union(parent, x, rem)   (the leftover is itself a prime)
    if x not in parent: parent[x] = x   (x == 1 has no prime factor)
return largest_group(parent, nums)   (count the numbers only, not the hubs)

find_all_people_with_secret.brute:
knows = all false; knows[0] = knows[first_person] = true
for each group of meetings sharing the same time, in time order:
    changed = true
    while changed:   (each sweep carries the secret only one hop further)
        changed = false
        for each (x, y) in the group:
            if exactly one of knows[x], knows[y] is true: knows[x] = knows[y] = true, changed = true
return every person p with knows[p]

find_all_people_with_secret.optimal:
find(parent, x): path-halving root lookup
parent[x] = x for every person; parent[first_person] = 0   (person 0 is the permanent "knows" root)
for each group of meetings sharing the same time, in time order:
    for each (x, y) in the group:
        root_x = find(parent, x), root_y = find(parent, y)
        if root_x != root_y: parent[root_x] = root_y
    for each (x, y) in the group:   (links that never reached 0 must not outlive this time)
        if find(parent, x) != find(parent, 0): parent[x] = x
        if find(parent, y) != find(parent, 0): parent[y] = y
return every person p with find(parent, p) == find(parent, 0)

minimum_cost_to_make_at_least_one_valid_.optimal:
MOVES = (right, left, down, up) for arrow values 1..4
step_cost(grid, row, col, k): 0 if grid[row][col] == k + 1 else 1
cost = INF for every cell, cost[0][0] = 0
queue = deque of (0, 0)
while the queue is not empty:   (0-1 BFS)
    (row, col) = pop from the front   (the front always holds a cheapest cell)
    for each direction k with in-bounds neighbour (nr, nc):
        step = step_cost(grid, row, col, k)   (free along the arrow, 1 to turn)
        if cost[row][col] + step < cost[nr][nc]:
            cost[nr][nc] = cost[row][col] + step
            if step == 0: push (nr, nc) to the front   (same cost layer: before any paid move)
            else: push (nr, nc) to the back
return cost[m - 1][n - 1]

swim_in_rising_water.optimal:
heap = min-heap of (highest elevation on the path so far, row, col) holding (grid[0][0], 0, 0)
seen = {(0, 0)}
while the heap is not empty:
    (level, row, col) = pop the smallest
    if (row, col) == (n - 1, n - 1): return level   (the first time the goal pops, its level is the smallest)
    for each in-bounds neighbour (nr, nc) not in seen:
        add (nr, nc) to seen   (later pops are at least this high: they cannot do better)
        push (max(level, grid[nr][nc]), nr, nc)
return -1

minimum_weighted_subgraph_with_the_requi.optimal:
dijkstra(adj, src):
    dist = INF everywhere, dist[src] = 0; heap = min-heap of (dist, node) holding (0, src)
    while the heap is not empty:
        (d, u) = pop the smallest
        if d > dist[u]: continue   (stale entry)
        for each (v, w) in adj[u]:
            if d + w < dist[v]: dist[v] = d + w, push (dist[v], v)
    return dist
forward = adjacency of (v, w) per node; backward = the same edges reversed
d1 = dijkstra(forward, src1), d2 = dijkstra(forward, src2), dd = dijkstra(backward, dest)   (dd[x] = shortest x -> dest)
best = infinity
for each node x: if d1[x] + d2[x] + dd[x] < best: best = that sum   (x is where the two paths merge)
return -1 if best == infinity else best

find_critical_and_pseudo_critical_edges_.brute:
is_spanning_tree(n, edges, chosen): exactly n - 1 edges and union-find finds no cycle among them
classify(edges, trees): index i is critical if it is in every tree, pseudo-critical if in some but not all
best = infinity, trees = []
for each mask from 0 to 2^E - 1:   (bit i set = edge i is in the candidate tree)
    chosen = the set edge indices, weight = their total weight
    if weight > best or not is_spanning_tree(n, edges, chosen): continue
    if weight < best: best = weight, trees = []   (a lighter tree: forget the heavier ones)
    append chosen to trees
return classify(edges, trees)
